<script setup lang="ts">
import {ref,onMounted,onUnmounted,nextTick,useId} from 'vue';
const props=defineProps<{title:string;wide?:boolean;busy?:boolean}>();const emit=defineEmits<{close:[]}>();const panel=ref<HTMLElement|null>(null),titleId=useId();let previous:Element|null=null,overflow='';
function key(e:KeyboardEvent){if(e.key==='Escape'&&!props.busy){emit('close');return;}if(e.key!=='Tab')return;const nodes=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')||[]).filter(n=>n.offsetParent!==null);if(!nodes.length){e.preventDefault();panel.value?.focus();return;}const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
onMounted(async()=>{previous=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';document.addEventListener('keydown',key);await nextTick();panel.value?.focus();});onUnmounted(()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);if(previous instanceof HTMLElement)previous.focus();});
</script>
<template><Teleport to="body"><div class="modal-backdrop"><section ref="panel" class="modal" :class="{wide}" role="dialog" aria-modal="true" :aria-labelledby="titleId" tabindex="-1"><header class="modal-header"><h2 :id="titleId">{{title}}</h2><button class="icon-button secondary" :disabled="busy" aria-label="Cerrar ventana" @click="emit('close')">×</button></header><slot /></section></div></Teleport></template>
